{
  "name": "@amykit/workflow-pull-request",
  "version": "0.8.0",
  "description": "A workflow other workflows call: open a pull request for a branch, through whichever code host is mounted.",
  "type": "module",
  "license": "MIT",
  "author": "Nicolas Melo",
  "homepage": "https://github.com/nicolasmelo1/amy#readme",
  "bugs": "https://github.com/nicolasmelo1/amy/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/nicolasmelo1/amy.git",
    "directory": "examples/workflow-pull-request"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "workflow.mmd"
  ],
  "dependencies": {
    "@amykit/core": "^0.8.0"
  },
  "devDependencies": {
    "@amykit/workflow-testkit": "^0.8.0"
  }
}

import { Plan, PullRequestView, WorkRecord, act, advance, settled, wait } from "@amykit/core";

export type PullRequestState = "OPENING" | "OPENED" | "REFUSED";

/** What a caller passes. A type rather than an interface, so it is a record of settings like any other input. */
export type PullRequestInput = {
  repo: string;
  branch: string;
  title: string;
  body: string;
  base?: string;
  mentions?: string;
};

export interface PullRequestRecord extends WorkRecord {
  state: PullRequestState;
  input: PullRequestInput;
  /** The number the host answered with when it opened one, before a look has found it. */
  requested?: number;
  /** What the host said when it answered that it would not open one. */
  refusal?: string;
  pullRequest?: { number: number; url: string };
}

export interface Observation {
  /** The pull request on the branch, or the one whose title names `mentions`, or none. */
  pullRequest: PullRequestView | null;
}

export interface Policy {
  /** How long to wait for a pull request the host said it opened to be one it shows. */
  settleMs: number;
}

export const DEFAULT_POLICY: Policy = { settleMs: 30_000 };

export type Effect = { type: "open-pull-request" };

type Decision = (record: PullRequestRecord, observation: Observation, policy: Policy) => Plan;

export const decide = {
  OPENING: planOpening,
  OPENED: () => settled("the pull request exists, and what happens to it is the caller's"),
  REFUSED: () => settled("the host would not open a pull request, and the caller was given its reason"),
} satisfies Record<PullRequestState, Decision>;

/**
 * Finds the pull request before it opens one, so a look that runs again
 * after a crash — or a branch somebody already opened by hand — never opens
 * a second.
 */
function planOpening(record: PullRequestRecord, observation: Observation, policy: Policy): Plan {
  if (observation.pullRequest) {
    return advance("OPENED", `pull request #${observation.pullRequest.number} is open on ${record.input.branch}`);
  }
  // The host said it opened one and does not show it yet: asking again
  // would open a second.
  if (record.requested !== undefined) {
    return wait(policy.settleMs, `the host opened #${record.requested} and does not show it yet`);
  }
  // An answer, not an outage: asking again would hear it again. An outage
  // never reaches here — it fails the look, and the engine retries it.
  if (record.refusal !== undefined) {
    return advance("REFUSED", `the host would not open a pull request on ${record.input.branch}: ${record.refusal}`);
  }
  return act(`the branch ${record.input.branch} has no pull request yet`, { type: "open-pull-request" });
}

export { DEFAULT_POLICY, decide } from "./decide.js";
export type { Effect, Observation, Policy, PullRequestInput, PullRequestRecord, PullRequestState } from "./decide.js";
export { configSchema, plugin } from "./plugin.js";

import { CodeHost, ConfigSchema, defineWorkflow, isCodeHostRefusal, port, withDiagramBeside } from "@amykit/core";
import { DEFAULT_POLICY, Observation, PullRequestRecord, decide } from "./decide.js";

/** The settings one call site gives it, and the only ones it has. */
export const configSchema = {
  draft: {
    type: "boolean",
    default: false,
    description: "open the pull request as a draft, for work nobody is waiting on at the moment it lands",
  },
  "policy.settleMs": {
    type: "number",
    default: 30_000,
    description: "how long to wait for a pull request the host opened to show, before looking again",
  },
} satisfies ConfigSchema;

const input = {
  repo: { type: "string", required: true, description: "the repository, as owner/name" },
  branch: { type: "string", required: true, description: "the branch the pull request is opened from, already on the remote" },
  title: { type: "string", required: true, description: "what the pull request is called" },
  body: { type: "string", default: "", description: "what the pull request says for itself" },
  base: { type: "string", description: "what it is opened against; left out, the host's default branch" },
  mentions: {
    type: "string",
    description: "an id the title names, so a pull request whose branch was renamed is still found rather than opened twice",
  },
} satisfies ConfigSchema;

const declared = defineWorkflow({
  name: "pull-request",
  pluginName: "@amykit/workflow-pull-request",
  configSchema,
  policy: DEFAULT_POLICY,
  // Through the port and nothing else, so the same workflow opens a merge
  // request wherever a plugin implements it. Finding by title is a method a
  // host only offers optionally, so it is asked for here and refused at boot.
  needs: { "code-host": port<CodeHost>({ requires: ["findPullRequestMentioning"] }) },
  codeHostWrites: ["open-pull-request"],
  input,
  output: {
    OPENED: (record: PullRequestRecord) => ({ number: record.pullRequest!.number, url: record.pullRequest!.url }),
    REFUSED: (record: PullRequestRecord) => ({ reason: record.refusal ?? "the host gave no reason" }),
  },
  decide,
  record: () => ({}),
  observe: async (scope, record: PullRequestRecord): Promise<Observation> => {
    // The host already answered no: that answer is final, and asking the host
    // anything more could only turn it into an outage.
    if (record.refusal !== undefined) return { pullRequest: null };
    const host = scope.ports["code-host"];
    const { repo, branch, mentions } = record.input;
    // The one this call opened is read by its number first: the branch may
    // since carry another, and a merged or closed one is still this call's.
    if (record.requested !== undefined) {
      const opened = await host.pullRequest(repo, record.requested);
      if (opened) return { pullRequest: opened };
    }
    const byBranch = await host.findPullRequest(repo, branch);
    if (byBranch || mentions === undefined) return { pullRequest: byBranch };
    return { pullRequest: (await host.findPullRequestMentioning?.(repo, mentions)) ?? null };
  },
  actions: {
    "open-pull-request": async (scope, work) => {
      const { repo, branch, title, body, base } = (work.record as PullRequestRecord).input;
      try {
        work.outcomes.requested = await scope.ports["code-host"].openPullRequest({
          repo,
          branch,
          title,
          body,
          ...(base === undefined ? {} : { base }),
          ...(scope.config.draft ? { draft: true } : {}),
        });
      } catch (error) {
        // The host's own words are the reason the caller is handed. Anything
        // that is not its answer is the engine's to retry.
        if (!isCodeHostRefusal(error)) throw error;
        work.outcomes.refusal = error.message;
      }
    },
  },
  remember: (_scope, record: PullRequestRecord, outcomes, observation: Observation) => {
    const next: PullRequestRecord = { ...record };
    if (typeof outcomes.requested === "number") next.requested = outcomes.requested;
    if (typeof outcomes.refusal === "string") next.refusal = outcomes.refusal;
    if (observation.pullRequest) next.pullRequest = { number: observation.pullRequest.number, url: observation.pullRequest.url };
    return next;
  },
});

/**
 * Drawn by its own diagram, because a caller imports it as a value: no host
 * reads the directory a callee was installed into.
 */
export const plugin = withDiagramBeside(declared, import.meta.url);
